Here is the commit message:
drm/drv: propagate errors from drm_modeset_register_all()

In case the drm_modeset_register_all() function fails, its error code
will be ignored. Instead make the drm_dev_register() bail out in case of
such an error.

Fixes: 79190ea2658a ("drm: Add callbacks for late registering")
Reviewed-by: Neil Armstrong <neil.armstrong@linaro.org>
Signed-off-by: Dmitry Baryshkov <dmitry.baryshkov@linaro.org>
Signed-off-by: Maxime Ripard <mripard@kernel.org>
Link: https://patchwork.freedesktop.org/patch/msgid/20231202225552.1283638-1-dmitry.baryshkov@linaro.org

Here is the root cause:
The bug was caused by the failure to handle the error return value from the `drm_modeset_register_all()` function. When this function fails, the error code was ignored, allowing the `drm_dev_register()` function to continue executing without properly managing the failure, which could lead to inconsistent device states or resource leaks.

Here is the patch:
  */
 int drm_dev_register(struct drm_device *dev, unsigned long flags)
 {
 	const struct drm_driver *driver = dev->driver;
 	int ret;

 	if (!driver->load)
 		drm_mode_config_validate(dev);

 	WARN_ON(!dev->managed.final_kfree);

 	if (drm_dev_needs_global_mutex(dev))
 		mutex_lock(&drm_global_mutex);

 	if (drm_core_check_feature(dev, DRIVER_COMPUTE_ACCEL))
 		accel_debugfs_register(dev);
 	else
 		drm_debugfs_dev_register(dev);

 	ret = drm_minor_register(dev, DRM_MINOR_RENDER);
 	if (ret)
 		goto err_minors;

 	ret = drm_minor_register(dev, DRM_MINOR_PRIMARY);
 	if (ret)
 		goto err_minors;

 	ret = drm_minor_register(dev, DRM_MINOR_ACCEL);
 	if (ret)
 		goto err_minors;

 	ret = create_compat_control_link(dev);
 	if (ret)
 		goto err_minors;

 	dev->registered = true;

 	if (driver->load) {
 		ret = driver->load(dev, flags);
 		if (ret)
 			goto err_minors;
 	}

-	if (drm_core_check_feature(dev, DRIVER_MODESET))
-		drm_modeset_register_all(dev);
+	if (drm_core_check_feature(dev, DRIVER_MODESET)) {
+		ret = drm_modeset_register_all(dev);
+		if (ret)
+			goto err_unload;
+	}

 	DRM_INFO("Initialized %s %d.%d.%d %s for %s on minor %d\n",
 		 driver->name, driver->major, driver->minor,
 		 driver->patchlevel, driver->date,
 		 dev->dev ? dev_name(dev->dev) : "virtual device",
 		 dev->primary ? dev->primary->index : dev->accel->index);

 	goto out_unlock;

+err_unload:
+	if (dev->driver->unload)
+		dev->driver->unload(dev);
 err_minors:
 	remove_compat_control_link(dev);
 	drm_minor_unregister(dev, DRM_MINOR_ACCEL);
 	drm_minor_unregister(dev, DRM_MINOR_PRIMARY);
 	drm_minor_unregister(dev, DRM_MINOR_RENDER);
 out_unlock:
 	if (drm_dev_needs_global_mutex(dev))
 		mutex_unlock(&drm_global_mutex);
 	return ret;
 }
 EXPORT_SYMBOL(drm_dev_register);


